      "app/src/main/java/com/rama/mako/managers/AppListManager.kt": {
        "binary": false,
        "truncated": false,
        "patch": "diff --git a/app/src/main/java/com/rama/mako/managers/AppListManager.kt b/app/src/main/java/com/rama/mako/managers/AppListManager.kt\nindex 211996e..87579ae 100644\n--- a/app/src/main/java/com/rama/mako/managers/AppListManager.kt\n+++ b/app/src/main/java/com/rama/mako/managers/AppListManager.kt\n@@ -7,6 +7,7 @@ import android.net.Uri\n import android.os.Build\n import android.provider.Settings\n import android.text.format.Formatter\n+import android.util.TypedValue\n import android.view.LayoutInflater\n import android.view.View\n import android.view.View.generateViewId\n@@ -97,6 +98,7 @@ class AppListManager(\n         if (layoutManager.spanCount != columnCount) {\n             layoutManager.spanCount = columnCount\n         }\n+        recyclerView.layoutDirection = if (prefs.isRtlRowEnabled()) View.LAYOUT_DIRECTION_RTL else View.LAYOUT_DIRECTION_LTR\n         updateAppsCache()\n         buildItems()\n     }\n@@ -852,6 +854,7 @@ class AppListManager(\n     private fun configureRecyclerView() {\n         layoutManager = GridLayoutManager(context, computeColumnCount())\n         recyclerView.layoutManager = layoutManager\n+        recyclerView.layoutDirection = if (prefs.isRtlRowEnabled()) View.LAYOUT_DIRECTION_RTL else View.LAYOUT_DIRECTION_LTR\n         recyclerView.adapter = adapter\n     }\n \n@@ -919,22 +922,34 @@ class AppListManager(\n     }\n \n     private fun bindGroupHeader(holder: GroupHeaderViewHolder, item: ListItem.Header) {\n+        val isRtl = prefs.isRtlRowEnabled()\n+        holder.itemView.layoutDirection = if (isRtl) View.LAYOUT_DIRECTION_RTL else View.LAYOUT_DIRECTION_LTR\n+        holder.text.layoutDirection = if (isRtl) View.LAYOUT_DIRECTION_RTL else View.LAYOUT_DIRECTION_LTR\n+        holder.text.textAlignment = View.TEXT_ALIGNMENT_VIEW_START\n+\n         val pinned = prefs.isGroupKeepExpanded(item.id)\n         val collapsible = prefs.hasCollapsibleGroups() && !pinned\n         val isExpanded = pinned || (collapsible && prefs.isGroupExpanded(item.id))\n-        val collapseIndicator = if (collapsible) {\n+        val indicatorSymbol = if (collapsible) {\n             context.getString(\n                 if (isExpanded) {\n                     BohioR.string.settings_section_collapse_indicator\n                 } else {\n                     BohioR.string.settings_section_expand_indicator\n                 }\n-            ) + \" \"\n+            )\n         } else {\n             \"\"\n         }\n \n-        holder.text.text = collapseIndicator + item.title.uppercase()\n+        val titleText = item.title.uppercase()\n+        holder.text.text = if (indicatorSymbol.isEmpty()) {\n+            titleText\n+        } else if (isRtl) {\n+            \"$titleText $indicatorSymbol\"\n+        } else {\n+            \"$indicatorSymbol $titleText\"\n+        }\n         ThemeManager.applyTheme(context, holder.text)\n         ViewCompat.setAccessibilityHeading(holder.itemView, true)\n         holder.itemView.isFocusable = collapsible\n@@ -985,6 +1000,20 @@ class AppListManager(\n         renderAppInfo(view, app)\n         view.isFocusable = true\n \n+        val isRtl = prefs.isRtlRowEnabled()\n+        view.layoutDirection = if (isRtl) View.LAYOUT_DIRECTION_RTL else View.LAYOUT_DIRECTION_LTR\n+\n+        val fontSize = prefs.getAppFontSize()\n+        holder.label.setTextSize(TypedValue.COMPLEX_UNIT_SP, fontSize.toFloat())\n+\n+        val rowSpacingPx = spToPx(context, prefs.getAppRowSpacing().toFloat())\n+        holder.label.setPaddingRelative(\n+            holder.label.paddingStart,\n+            rowSpacingPx,\n+            holder.label.paddingEnd,\n+            rowSpacingPx\n+        )\n+\n         val key = getSelectionKey(app)\n         val isSelected = key in selectedApps\n         holder.selectionCheck.visibility = if (isMultiSelectMode) View.VISIBLE else View.GONE\n"
      },
      "app/src/main/java/com/rama/mako/managers/PrefsManager.kt": {
        "binary": false,
        "truncated": false,
        "patch": "diff --git a/app/src/main/java/com/rama/mako/managers/PrefsManager.kt b/app/src/main/java/com/rama/mako/managers/PrefsManager.kt\nindex 5d75873..069c035 100644\n--- a/app/src/main/java/com/rama/mako/managers/PrefsManager.kt\n+++ b/app/src/main/java/com/rama/mako/managers/PrefsManager.kt\n@@ -28,6 +28,9 @@ class PrefsManager private constructor(context: Context) : BohioPrefsManager(con\n         const val APPS_SHOW_API_INDICATORS = \"apps:show_api_indicators\"\n         const val APPS_SHOW_SIZE = \"apps:show_size\"\n         const val APPS_SHOW_SHORTCUTS = \"apps:show_shortcuts\"\n+        const val APPS_RTL_ROW = \"apps:rtl_row\"\n+        const val APPS_FONT_SIZE = \"apps:font_size\"\n+        const val APPS_ROW_SPACING = \"apps:row_spacing\"\n \n         const val HOME_BACKGROUND_MODE = \"home:background_mode\"\n         const val HOME_BACKGROUND_MODE_SCREEN_OPACITY_STRENGTH =\n@@ -171,6 +174,9 @@ class PrefsManager private constructor(context: Context) : BohioPrefsManager(con\n         editor.putBoolean(FileKeys.APPS_SHOW_API_INDICATORS, false)\n         editor.putBoolean(FileKeys.APPS_SHOW_SIZE, false)\n         editor.putBoolean(FileKeys.APPS_SHOW_SHORTCUTS, false)\n+        editor.putBoolean(FileKeys.APPS_RTL_ROW, false)\n+        editor.putInt(FileKeys.APPS_FONT_SIZE, 32)\n+        editor.putInt(FileKeys.APPS_ROW_SPACING, 12)\n \n         editor.putString(FileKeys.HOME_BACKGROUND_MODE, BackgroundMode.DEFAULT)\n         editor.putInt(FileKeys.HOME_BACKGROUND_MODE_SCREEN_OPACITY_STRENGTH, 9)\n@@ -448,6 +454,24 @@ class PrefsManager private constructor(context: Context) : BohioPrefsManager(con\n     fun hasAppShortcuts(): Boolean =\n         prefs.getBoolean(FileKeys.APPS_SHOW_SHORTCUTS, false)\n \n+    fun isRtlRowEnabled(): Boolean =\n+        prefs.getBoolean(FileKeys.APPS_RTL_ROW, false)\n+\n+    fun setRtlRowEnabled(enabled: Boolean) =\n+        prefs.edit().putBoolean(FileKeys.APPS_RTL_ROW, enabled).apply()\n+\n+    fun getAppFontSize(): Int =\n+        prefs.getInt(FileKeys.APPS_FONT_SIZE, 32)\n+\n+    fun setAppFontSize(size: Int) =\n+        prefs.edit().putInt(FileKeys.APPS_FONT_SIZE, size).apply()\n+\n+    fun getAppRowSpacing(): Int =\n+        prefs.getInt(FileKeys.APPS_ROW_SPACING, 12)\n+\n+    fun setAppRowSpacing(spacing: Int) =\n+        prefs.edit().putInt(FileKeys.APPS_ROW_SPACING, spacing).apply()\n+\n     fun setMultiColumnEnabled(enabled: Boolean) =\n         prefs.edit().putBoolean(FileKeys.APPS_MULTI_COLUMN, enabled).apply()\n \n"
      },
