      "app/src/main/java/com/rama/mako/activities/ConfirmPinShortcutActivity.kt": {
        "binary": false,
        "truncated": false,
        "patch": "diff --git a/app/src/main/java/com/rama/mako/activities/ConfirmPinShortcutActivity.kt b/app/src/main/java/com/rama/mako/activities/ConfirmPinShortcutActivity.kt\nnew file mode 100644\nindex 0000000..780f0fa\n--- /dev/null\n+++ b/app/src/main/java/com/rama/mako/activities/ConfirmPinShortcutActivity.kt\n@@ -0,0 +1,64 @@\n+package com.rama.mako.activities\n+\n+import android.app.Activity\n+import android.app.AlertDialog\n+import android.content.Context\n+import android.content.pm.LauncherApps\n+import android.os.Build\n+import android.os.Bundle\n+import android.widget.Toast\n+import com.rama.mako.R\n+\n+class ConfirmPinShortcutActivity : Activity() {\n+\n+    override fun onCreate(savedInstanceState: Bundle?) {\n+        super.onCreate(savedInstanceState)\n+\n+        if (Build.VERSION.SDK_INT < Build.VERSION_CODES.O ||\n+            intent.action != LauncherApps.ACTION_CONFIRM_PIN_SHORTCUT\n+        ) {\n+            finish()\n+            return\n+        }\n+\n+        val launcherApps =\n+            getSystemService(Context.LAUNCHER_APPS_SERVICE) as LauncherApps\n+        val request = launcherApps.getPinItemRequest(intent)\n+        val shortcut = request\n+            ?.takeIf {\n+                it.requestType == LauncherApps.PinItemRequest.REQUEST_TYPE_SHORTCUT &&\n+                    it.isValid\n+            }\n+            ?.shortcutInfo\n+\n+        if (request == null || shortcut == null) {\n+            finish()\n+            return\n+        }\n+\n+        val label = shortcut.shortLabel?.toString()\n+            ?.ifBlank { null }\n+            ?: shortcut.longLabel?.toString()\n+            ?.ifBlank { null }\n+            ?: shortcut.`package`\n+\n+        AlertDialog.Builder(this)\n+            .setTitle(R.string.h2_add_shortcut)\n+            .setMessage(label)\n+            .setPositiveButton(R.string.btn_add_shortcut) { _, _ ->\n+                val accepted = runCatching {\n+                    request.isValid && request.accept()\n+                }.getOrDefault(false)\n+                val message = if (accepted) {\n+                    getString(R.string.toast_shortcut_added, label)\n+                } else {\n+                    getString(R.string.toast_unable_add_shortcut)\n+                }\n+                Toast.makeText(this, message, Toast.LENGTH_SHORT).show()\n+                finish()\n+            }\n+            .setNegativeButton(android.R.string.cancel) { _, _ -> finish() }\n+            .setOnCancelListener { finish() }\n+            .show()\n+    }\n+}\n"
      },
