      "app/src/main/res/layout/home_list_header.xml": {
        "binary": false,
        "truncated": false,
        "patch": "diff --git a/app/src/main/res/layout/home_list_header.xml b/app/src/main/res/layout/home_list_header.xml\nnew file mode 100644\nindex 0000000..93c0007\n--- /dev/null\n+++ b/app/src/main/res/layout/home_list_header.xml\n@@ -0,0 +1,84 @@\n+<?xml version=\"1.0\" encoding=\"utf-8\"?>\n+<LinearLayout xmlns:android=\"http://schemas.android.com/apk/res/android\"\n+    xmlns:app=\"http://schemas.android.com/apk/res-auto\"\n+    android:id=\"@+id/apps_layout\"\n+    android:gravity=\"start\"\n+    style=\"@style/HorizontalList\">\n+\n+    <LinearLayout\n+        android:orientation=\"vertical\"\n+        android:layout_width=\"0dp\"\n+        android:layout_height=\"wrap_content\"\n+        android:layout_weight=\"1\"\n+        android:paddingBottom=\"16sp\">\n+\n+        <Button\n+            android:id=\"@+id/time\"\n+            android:background=\"@android:color/transparent\"\n+            android:layout_width=\"wrap_content\"\n+            android:focusable=\"false\"\n+            style=\"@style/H1\" />\n+\n+        <LinearLayout\n+            android:id=\"@+id/date_row\"\n+            android:paddingBottom=\"4sp\"\n+            android:gravity=\"start\"\n+            style=\"@style/HorizontalListDivided\">\n+\n+            <ImageView\n+                android:layout_width=\"16sp\"\n+                android:layout_height=\"16sp\"\n+                app:tint=\"@color/icon\"\n+                android:src=\"@drawable/px_calendar_today\" />\n+\n+            <TextView\n+                android:id=\"@+id/date\"\n+                android:textSize=\"16sp\"\n+                android:layout_width=\"wrap_content\"\n+                android:layout_height=\"wrap_content\"\n+                android:textColor=\"@color/foreground\" />\n+        </LinearLayout>\n+\n+        <LinearLayout\n+            android:id=\"@+id/battery_row\"\n+            style=\"@style/HorizontalListDivided\">\n+\n+            <ImageView\n+                android:layout_width=\"16sp\"\n+                android:layout_height=\"16sp\"\n+                app:tint=\"@color/icon\"\n+                android:src=\"@drawable/px_battery_full_alt\" />\n+\n+            <TextView\n+                android:id=\"@+id/battery\"\n+                android:textSize=\"16sp\"\n+                android:layout_width=\"wrap_content\"\n+                android:layout_height=\"wrap_content\"\n+                android:textColor=\"@color/foreground\" />\n+        </LinearLayout>\n+    </LinearLayout>\n+\n+    <FrameLayout\n+        android:id=\"@+id/lock_btn\"\n+        android:layout_width=\"wrap_content\"\n+        android:layout_height=\"wrap_content\"\n+        android:padding=\"12sp\">\n+\n+        <ImageView\n+            android:id=\"@+id/lock_icon\"\n+            android:src=\"@drawable/px_lock\"\n+            style=\"@style/Icon24\" />\n+    </FrameLayout>\n+\n+    <FrameLayout\n+        android:id=\"@+id/search_icon\"\n+        android:layout_width=\"wrap_content\"\n+        android:layout_height=\"wrap_content\"\n+        android:padding=\"12sp\">\n+\n+        <ImageView\n+            android:src=\"@drawable/px_search\"\n+            android:contentDescription=\"@string/altdescr_search_icon\"\n+            style=\"@style/Icon24\" />\n+    </FrameLayout>\n+</LinearLayout>\n"
      },
