      "app/src/main/java/com/rama/mako/services/ScreenLockAccessibilityService.kt": {
        "binary": false,
        "truncated": false,
        "patch": "diff --git a/app/src/main/java/com/rama/mako/services/ScreenLockAccessibilityService.kt b/app/src/main/java/com/rama/mako/services/ScreenLockAccessibilityService.kt\nnew file mode 100644\nindex 0000000..316ef51\n--- /dev/null\n+++ b/app/src/main/java/com/rama/mako/services/ScreenLockAccessibilityService.kt\n@@ -0,0 +1,24 @@\n+package com.rama.mako.services\n+\n+import android.accessibilityservice.AccessibilityService\n+import android.view.accessibility.AccessibilityEvent\n+\n+class ScreenLockAccessibilityService : AccessibilityService() {\n+\n+    companion object {\n+        var instance: ScreenLockAccessibilityService? = null\n+    }\n+\n+    override fun onServiceConnected() {\n+        instance = this\n+    }\n+\n+    override fun onAccessibilityEvent(event: AccessibilityEvent?) {}\n+\n+    override fun onInterrupt() {}\n+\n+    override fun onUnbind(intent: android.content.Intent?): Boolean {\n+        instance = null\n+        return super.onUnbind(intent)\n+    }\n+}\n"
      },
