      "app/build.gradle.kts": {
        "binary": false,
        "truncated": false,
        "patch": "diff --git a/app/build.gradle.kts b/app/build.gradle.kts\nindex a7be1ae..7abc2c3 100644\n--- a/app/build.gradle.kts\n+++ b/app/build.gradle.kts\n@@ -15,7 +15,7 @@ android {\n         applicationId = \"com.rama.mako\"\n         minSdk = 21\n         targetSdk = 36\n-        versionCode = 39\n+        versionCode = 40\n         versionName = \"$currentYear.$versionCode\"\n     }\n \n"
      },
      "app/src/main/java/com/rama/mako/CsActivity.kt": {
        "binary": false,
        "truncated": false,
        "patch": "diff --git a/app/src/main/java/com/rama/mako/CsActivity.kt b/app/src/main/java/com/rama/mako/CsActivity.kt\nindex f2087f7..01bfdff 100644\n--- a/app/src/main/java/com/rama/mako/CsActivity.kt\n+++ b/app/src/main/java/com/rama/mako/CsActivity.kt\n@@ -2,6 +2,7 @@ package com.rama.mako\n \n import android.app.Activity\n import android.content.Context\n+import android.content.res.Configuration\n import android.os.Build\n import android.os.Bundle\n import android.view.View\n@@ -12,21 +13,39 @@ import com.rama.mako.managers.ThemeManager\n import com.rama.mako.utils.dp\n import com.rama.mako.managers.PrefsManager\n import com.rama.mako.utils.LocaleHelper\n+import kotlin.text.toInt\n+import kotlin.times\n \n abstract class CsActivity : Activity() {\n \n     val prefs by lazy { PrefsManager.getInstance(this) }\n     private var lastKnownAppLanguage: String? = null\n     private var lastKnownTheme: String? = null\n+    private var lastKnownUiScale: Float = -1f\n \n     override fun attachBaseContext(newBase: Context) {\n-        super.attachBaseContext(LocaleHelper.wrapContext(newBase))\n+        val localeContext = LocaleHelper.wrapContext(newBase)\n+\n+        val scale = PrefsManager.getInstance(localeContext).getUiScale()\n+\n+        val context = if (scale != 1f) {\n+            // createConfigurationContext derives densityDpi from the *base* context\n+            // each time, so there is no compounding across recreate() calls.\n+            val config = Configuration(localeContext.resources.configuration)\n+            config.densityDpi = (localeContext.resources.displayMetrics.densityDpi * scale).toInt()\n+            localeContext.createConfigurationContext(config)\n+        } else {\n+            localeContext\n+        }\n+\n+        super.attachBaseContext(context)\n     }\n \n     override fun onCreate(savedInstanceState: Bundle?) {\n         super.onCreate(savedInstanceState)\n         lastKnownAppLanguage = prefs.getAppLanguage()\n         lastKnownTheme = prefs.getTheme()\n+        lastKnownUiScale = prefs.getUiScale()\n \n         // Allow drawing behind system bars\n         if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.R) {\n@@ -63,6 +82,13 @@ abstract class CsActivity : Activity() {\n             return\n         }\n \n+        val currentUiScale = prefs.getUiScale()\n+        if (currentUiScale != lastKnownUiScale) {\n+            lastKnownUiScale = currentUiScale\n+            recreate()\n+            return\n+        }\n+\n         val root = findViewById<View>(android.R.id.content)\n         ThemeManager.applyTheme(this, root)\n     }\n"
      },
      "app/src/main/java/com/rama/mako/activities/LockActivity.kt": {
        "binary": false,
        "truncated": false,
        "patch": "diff --git a/app/src/main/java/com/rama/mako/activities/LockActivity.kt b/app/src/main/java/com/rama/mako/activities/LockActivity.kt\nindex 02af757..1e362b1 100644\n--- a/app/src/main/java/com/rama/mako/activities/LockActivity.kt\n+++ b/app/src/main/java/com/rama/mako/activities/LockActivity.kt\n@@ -1,20 +1,33 @@\n package com.rama.mako.activities\n \n import android.content.Intent\n+import android.os.Build\n import android.os.Bundle\n import android.view.View\n import android.view.WindowManager\n import android.widget.Button\n import android.widget.EditText\n+import android.widget.TextView\n+import android.window.OnBackInvokedCallback\n import com.rama.mako.CsActivity\n import com.rama.mako.R\n \n class LockActivity : CsActivity() {\n \n     private lateinit var pinDisplay: EditText\n+    private lateinit var easterEggText: TextView\n+    private lateinit var easterEggCounter: TextView\n     private lateinit var buttons: List<Button>\n+    private lateinit var unlockButton: Button\n \n     private val pinBuilder = StringBuilder()\n+    private var unlockPressCount = 0\n+    private var isEasterEggActive = false\n+\n+    private val easterEggThreshold = 32\n+    private val easterEggCounterStart = 22\n+\n+    private var backCallback: OnBackInvokedCallback? = null\n \n     override fun onCreate(savedInstanceState: Bundle?) {\n         super.onCreate(savedInstanceState)\n@@ -32,11 +45,15 @@ class LockActivity : CsActivity() {\n         setupViews()\n         setupActions()\n         setupKeypad()\n+        setupBackHandling()\n         clearPin()\n     }\n \n     private fun setupViews() {\n         pinDisplay = findViewById(R.id.pin_display)\n+        easterEggText = findViewById(R.id.easter_egg_text)\n+        easterEggCounter = findViewById(R.id.easter_egg_counter)\n+        unlockButton = findViewById(R.id.unlock_button)\n \n         buttons = listOf(\n             findViewById(R.id.btn0),\n@@ -64,6 +81,25 @@ class LockActivity : CsActivity() {\n         finish()\n     }\n \n+    private fun setupBackHandling() {\n+        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.TIRAMISU) {\n+            backCallback = OnBackInvokedCallback {\n+                navigateToHome()\n+            }\n+            onBackInvokedDispatcher.registerOnBackInvokedCallback(\n+                android.window.OnBackInvokedDispatcher.PRIORITY_DEFAULT,\n+                backCallback!!\n+            )\n+        }\n+    }\n+\n+    override fun onDestroy() {\n+        super.onDestroy()\n+        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.TIRAMISU && backCallback != null) {\n+            onBackInvokedDispatcher.unregisterOnBackInvokedCallback(backCallback!!)\n+        }\n+    }\n+\n     private fun setupKeypad() {\n         val isRandomized = prefs.getBoolean(\n             com.rama.mako.managers.PrefsManager.PrefKeys.SECURITY_KEYPAD_RANDOMIZED,\n@@ -102,7 +138,17 @@ class LockActivity : CsActivity() {\n         }\n \n         findViewById<View>(R.id.unlock_button).setOnClickListener {\n-            validatePin()\n+            if (!isEasterEggActive) {\n+                unlockPressCount++\n+                if (unlockPressCount >= easterEggThreshold) {\n+                    showEasterEgg()\n+                } else if (unlockPressCount >= easterEggCounterStart) {\n+                    showEasterEggCounter()\n+                    validatePin()\n+                } else {\n+                    validatePin()\n+                }\n+            }\n         }\n \n         findViewById<View>(R.id.close_button).setOnClickListener {\n@@ -110,6 +156,19 @@ class LockActivity : CsActivity() {\n         }\n     }\n \n+    private fun showEasterEgg() {\n+        isEasterEggActive = true\n+        easterEggText.visibility = View.VISIBLE\n+        easterEggCounter.visibility = View.GONE\n+        unlockButton.isEnabled = false\n+    }\n+\n+    private fun showEasterEggCounter() {\n+        val remaining = easterEggThreshold - unlockPressCount\n+        easterEggCounter.text = getString(R.string.easter_eggs_counter, remaining)\n+        easterEggCounter.visibility = View.VISIBLE\n+    }\n+\n     private fun validatePin() {\n         val savedPin = prefs.getPin()\n \n"
      },
