      "app/src/main/java/com/rama/mako/BatteryManagerHelper.kt": {
        "binary": false,
        "truncated": false,
        "patch": "diff --git a/app/src/main/java/com/rama/mako/BatteryManagerHelper.kt b/app/src/main/java/com/rama/mako/BatteryManagerHelper.kt\nindex cfc2ecc..a773b70 100644\n--- a/app/src/main/java/com/rama/mako/BatteryManagerHelper.kt\n+++ b/app/src/main/java/com/rama/mako/BatteryManagerHelper.kt\n@@ -52,21 +52,15 @@ class BatteryManagerHelper(\n                 status == BatteryManager.BATTERY_STATUS_FULL\n             ) {\n                 when (chargePlug) {\n-                    BatteryManager.BATTERY_PLUGGED_USB -> \"USB\"\n-                    BatteryManager.BATTERY_PLUGGED_AC -> \"AC\"\n-                    BatteryManager.BATTERY_PLUGGED_WIRELESS -> \"Wireless\"\n+                    BatteryManager.BATTERY_PLUGGED_USB -> \"USB Charging\"\n+                    BatteryManager.BATTERY_PLUGGED_AC -> \"AC Charging\"\n+                    BatteryManager.BATTERY_PLUGGED_WIRELESS -> \"Wireless Charging\"\n                     else -> \"\"\n                 }\n             } else {\n                 \"\"\n             }\n \n-            val statusTextCombined = when {\n-                statusText == \"Charging\" && chargeType.isNotEmpty() -> chargeType\n-                statusText == \"Full\" -> \"Full\"\n-                else -> statusText\n-            }\n-\n             // Current in mA (may be negative if discharging)\n             val bm = context.getSystemService(Context.BATTERY_SERVICE) as BatteryManager\n             val currentMa =\n@@ -76,26 +70,39 @@ class BatteryManagerHelper(\n             val powerW = abs(voltageV * (currentMa / 1000f)) // mA → A\n \n             // Charging / discharging speed label\n-            val powerLabel = when {\n+            val speedLabel = when {\n                 status == BatteryManager.BATTERY_STATUS_CHARGING || status == BatteryManager.BATTERY_STATUS_FULL -> {\n                     when {\n-                        powerW < 2 -> \"Slow Charge\"\n-                        powerW < 10 -> \"Normal Charge\"\n-                        else -> \"Fast Charge\"\n+                        powerW < 2 -> \"Slow\"\n+                        powerW < 10 -> \"Normal\"\n+                        else -> \"Fast\"\n                     }\n                 }\n \n                 status == BatteryManager.BATTERY_STATUS_DISCHARGING -> {\n                     when {\n-                        powerW < 2 -> \"Slow Discharge\"\n-                        powerW < 10 -> \"Normal Discharge\"\n-                        else -> \"Fast Discharge\"\n+                        powerW < 2 -> \"Slow\"\n+                        powerW < 10 -> \"Normal\"\n+                        else -> \"Fast\"\n                     }\n                 }\n \n                 else -> \"\"\n             }\n \n+            // Combine status + speed\n+            val statusCombined = when {\n+                statusText == \"Full\" -> \"Full\"\n+                speedLabel.isNotEmpty() -> \"$statusText ($speedLabel)\"\n+                else -> statusText\n+            }\n+\n+            // Add charge type if charging\n+            val statusFinal = when {\n+                statusText == \"Charging\" && chargeType.isNotEmpty() -> \"$chargeType ($speedLabel)\"\n+                else -> statusCombined\n+            }\n+\n             if (level >= 0 && scale > 0) {\n                 val levelPct = (level * 100 / scale.toFloat()).toInt()\n                 val tempDisplay =\n@@ -107,8 +114,7 @@ class BatteryManagerHelper(\n                     tempDisplay,\n                     \"${voltageMv} mV\",\n                     \"${currentMa.toInt()} mA\",\n-                    statusTextCombined,\n-                    powerLabel.ifEmpty { null } // avoid empty trace\n+                    statusFinal.ifEmpty { null } // avoid empty trace\n                 ).filterNotNull()\n \n                 val info = infoParts.joinToString(\" :: \")\n"
      }
