      "app/src/main/res/layout/app_list_item.xml": {
        "binary": false,
        "truncated": false,
        "patch": "diff --git a/app/src/main/res/layout/app_list_item.xml b/app/src/main/res/layout/app_list_item.xml\nindex 61ac23b..9518355 100644\n--- a/app/src/main/res/layout/app_list_item.xml\n+++ b/app/src/main/res/layout/app_list_item.xml\n@@ -1,9 +1,93 @@\n-<?xml version=\"1.0\" encoding=\"utf-8\"?>\n-<TextView xmlns:android=\"http://schemas.android.com/apk/res/android\"\n-    android:id=\"@+id/text1\"\n+<LinearLayout xmlns:android=\"http://schemas.android.com/apk/res/android\"\n+    android:orientation=\"vertical\"\n     android:layout_width=\"match_parent\"\n-    android:layout_height=\"wrap_content\"\n-    android:textColor=\"@color/foreground_color\"\n-    android:padding=\"8dp\"\n-    android:textSize=\"16sp\"\n-    android:gravity=\"start\" />\n+    android:layout_height=\"wrap_content\">\n+\n+    <!-- Divider, hidden by default -->\n+    <View\n+        android:id=\"@+id/favorite_divider\"\n+        android:layout_width=\"match_parent\"\n+        android:layout_height=\"1dp\"\n+        android:background=\"#aaa\"\n+        android:visibility=\"gone\" />\n+\n+    <!-- Horizontal row -->\n+\n+    <LinearLayout\n+        android:orientation=\"horizontal\"\n+        android:layout_width=\"match_parent\"\n+        android:layout_height=\"wrap_content\"\n+        android:gravity=\"center_vertical\">\n+\n+        <!-- Open app button -->\n+        <TextView\n+            android:id=\"@+id/open_app_button\"\n+            android:layout_width=\"0dp\"\n+            android:layout_height=\"wrap_content\"\n+            android:layout_weight=\"1\"\n+            android:paddingTop=\"8dp\"\n+            android:paddingBottom=\"8dp\"\n+            android:textColor=\"@color/foreground_color\"\n+            android:textSize=\"16sp\"\n+            android:gravity=\"start|center_vertical\" />\n+\n+        <!-- Actions container -->\n+        <FrameLayout\n+            android:id=\"@+id/actions_container\"\n+            android:layout_width=\"wrap_content\"\n+            android:layout_height=\"wrap_content\"\n+            android:padding=\"4dp\"\n+            android:visibility=\"gone\"\n+            android:background=\"@color/star_bg\">\n+\n+            <LinearLayout\n+                android:orientation=\"horizontal\"\n+                android:layout_width=\"wrap_content\"\n+                android:layout_height=\"wrap_content\"\n+\n+                android:gravity=\"center_vertical\">\n+\n+                <FrameLayout\n+                    android:id=\"@+id/favorite_button\"\n+                    android:layout_width=\"wrap_content\"\n+                    android:layout_height=\"wrap_content\"\n+                    android:padding=\"4dp\"\n+                    android:clickable=\"true\"\n+                    android:focusable=\"true\">\n+\n+                    <ImageView\n+                        android:id=\"@+id/favorite_icon\"\n+                        android:layout_width=\"22dp\"\n+                        android:layout_height=\"22dp\"\n+                        android:src=\"@drawable/star_toggle\" />\n+                </FrameLayout>\n+\n+                <FrameLayout\n+                    android:id=\"@+id/close_button\"\n+                    android:layout_width=\"wrap_content\"\n+                    android:layout_height=\"wrap_content\"\n+                    android:padding=\"4dp\"\n+                    android:clickable=\"true\"\n+                    android:focusable=\"true\">\n+\n+                    <ImageView\n+                        android:layout_width=\"22dp\"\n+                        android:layout_height=\"22dp\"\n+                        android:src=\"@drawable/close\" />\n+                </FrameLayout>\n+            </LinearLayout>\n+        </FrameLayout>\n+    </LinearLayout>\n+\n+    <TextView\n+        android:id=\"@+id/favorite_bottom_border\"\n+        android:layout_width=\"match_parent\"\n+        android:layout_height=\"wrap_content\"\n+        android:textColor=\"@color/star_color\"\n+        android:text=\"* * * * * * * * * * * * * * * * * * *\"\n+        android:textSize=\"16sp\"\n+        android:layout_marginTop=\"16dp\"\n+        android:layout_marginBottom=\"16dp\"\n+        android:gravity=\"start|center_vertical\"\n+        android:visibility=\"gone\" />\n+</LinearLayout>\n"
      },
