      ".github/workflows/android.yml": {
        "binary": false,
        "truncated": false,
        "patch": "diff --git a/.github/workflows/android.yml b/.github/workflows/android.yml\nnew file mode 100644\nindex 0000000..dd56e99\n--- /dev/null\n+++ b/.github/workflows/android.yml\n@@ -0,0 +1,30 @@\n+name: Android Tests\n+\n+on:\n+  push:\n+  pull_request:\n+\n+jobs:\n+  androidTest:\n+    runs-on: ubuntu-latest\n+\n+    steps:\n+      - name: Checkout\n+        uses: actions/checkout@v4\n+\n+      - name: Set up JDK\n+        uses: actions/setup-java@v4\n+        with:\n+          distribution: temurin\n+          java-version: 17\n+\n+      - name: Set up Android SDK\n+        uses: android-actions/setup-android@v3\n+\n+      - name: Create AVD and run tests\n+        uses: reactivecircus/android-emulator-runner@v2\n+        with:\n+          api-level: 33\n+          target: default\n+          arch: x86_64\n+          script: ./gradlew connectedAndroidTest\n"
      },
      "app/build.gradle.kts": {
        "binary": false,
        "truncated": false,
        "patch": "diff --git a/app/build.gradle.kts b/app/build.gradle.kts\nindex 54d6124..7cb8a02 100644\n--- a/app/build.gradle.kts\n+++ b/app/build.gradle.kts\n@@ -1,6 +1,3 @@\n-androidTestImplementation 'androidx.test.ext:junit:1.1.5'\n-androidTestImplementation 'androidx.test.espresso:espresso-core:3.5.1'\n-\n plugins {\n     alias(libs.plugins.android.application)\n     alias(libs.plugins.kotlin.android)\n@@ -14,8 +11,11 @@ android {\n         applicationId = \"com.rama.mako\"\n         minSdk = 26\n         targetSdk = 36\n-        versionCode = 3\n-        versionName = \"20251226\"\n+        versionCode = 4\n+        versionName = \"20251228\"\n+\n+        // Required for instrumentation tests\n+        testInstrumentationRunner = \"androidx.test.runner.AndroidJUnitRunner\"\n     }\n \n     buildTypes {\n@@ -35,5 +35,14 @@ android {\n }\n \n dependencies {\n+    // App\n     implementation(libs.androidx.core.ktx)\n+\n+    // Local unit tests (JVM)\n+    testImplementation(\"junit:junit:4.13.2\")\n+\n+    // Instrumentation tests (device / emulator)\n+    androidTestImplementation(\"androidx.test.ext:junit:1.1.5\")\n+    androidTestImplementation(\"androidx.test.espresso:espresso-core:3.5.1\")\n }\n+\n"
      },
