      "app/src/main/java/com/rama/mako/ClockManager.kt": {
        "binary": false,
        "truncated": false,
        "patch": "diff --git a/app/src/main/java/com/rama/mako/ClockManager.kt b/app/src/main/java/com/rama/mako/ClockManager.kt\nindex 6e6d2d4..32b0817 100644\n--- a/app/src/main/java/com/rama/mako/ClockManager.kt\n+++ b/app/src/main/java/com/rama/mako/ClockManager.kt\n@@ -3,22 +3,42 @@ package com.rama.mako\n import android.os.Handler\n import android.os.Looper\n import android.widget.TextView\n-import java.text.SimpleDateFormat\n-import java.util.*\n+import java.time.LocalDateTime\n+import java.time.format.DateTimeFormatter\n+import java.time.format.TextStyle\n+import java.util.Locale\n \n class ClockManager(\n     private val timeTextView: TextView,\n     private val dateTextView: TextView\n ) {\n     private val handler = Handler(Looper.getMainLooper())\n-    private val timeFormat = SimpleDateFormat(\"HH:mm\", Locale.getDefault())\n-    private val dateFormat = SimpleDateFormat(\"dd MMM yyyy\", Locale.getDefault())\n+\n+    private val timeFormatter =\n+        DateTimeFormatter.ofPattern(\"HH:mm\")\n+\n+    private val dateFormatter =\n+        DateTimeFormatter.ofPattern(\"yyyy-MM-dd\")\n \n     private val runnable = object : Runnable {\n         override fun run() {\n-            val now = Date()\n-            timeTextView.text = timeFormat.format(now)\n-            dateTextView.text = dateFormat.format(now)\n+            val now = LocalDateTime.now()\n+            val locale = Locale.getDefault()\n+\n+            // Time\n+            timeTextView.text = now.format(timeFormatter)\n+\n+            // Date parts\n+            val weekday = now.dayOfWeek\n+                .getDisplayName(TextStyle.FULL, locale)\n+\n+            val dayOfYear = now.dayOfYear\n+            val totalDays = now.toLocalDate().lengthOfYear()\n+\n+            dateTextView.text =\n+                \"$weekday :: ${now.format(dateFormatter)} :: $dayOfYear/$totalDays\"\n+                    .uppercase(locale)\n+\n             handler.postDelayed(this, 1000)\n         }\n     }\n@@ -26,4 +46,3 @@ class ClockManager(\n     fun start() = handler.post(runnable)\n     fun stop() = handler.removeCallbacks(runnable)\n }\n-\n"
      },
