        "truncated": false,
        "patch": "diff --git a/app/src/main/java/com/rama/mako/ClockManager.kt b/app/src/main/java/com/rama/mako/ClockManager.kt\nindex 8d7d424..6e6d2d4 100644\n--- a/app/src/main/java/com/rama/mako/ClockManager.kt\n+++ b/app/src/main/java/com/rama/mako/ClockManager.kt\n@@ -8,10 +8,8 @@ import java.util.*\n \n class ClockManager(\n     private val timeTextView: TextView,\n-    private val dateTextView: TextView,\n-    private val updateStatusLine: (String) -> Unit // optional callback for combined status line\n+    private val dateTextView: TextView\n ) {\n-\n     private val handler = Handler(Looper.getMainLooper())\n     private val timeFormat = SimpleDateFormat(\"HH:mm\", Locale.getDefault())\n     private val dateFormat = SimpleDateFormat(\"dd MMM yyyy\", Locale.getDefault())\n@@ -19,26 +17,13 @@ class ClockManager(\n     private val runnable = object : Runnable {\n         override fun run() {\n             val now = Date()\n-            val formattedTime = timeFormat.format(now)\n-            val formattedDate = dateFormat.format(now)\n-\n-            // Update the TextViews\n-            timeTextView.text = formattedTime\n-            dateTextView.text = formattedDate\n-\n-            // Optional: update combined status line if needed\n-            updateStatusLine(formattedDate)\n-\n-            // Repeat every second\n+            timeTextView.text = timeFormat.format(now)\n+            dateTextView.text = dateFormat.format(now)\n             handler.postDelayed(this, 1000)\n         }\n     }\n \n-    fun start() {\n-        handler.post(runnable)\n-    }\n-\n-    fun stop() {\n-        handler.removeCallbacks(runnable)\n-    }\n+    fun start() = handler.post(runnable)\n+    fun stop() = handler.removeCallbacks(runnable)\n }\n+\n"
