      "app/src/main/java/com/rama/colibri/MainActivity.kt": {
        "binary": false,
        "truncated": false,
        "patch": "diff --git a/app/src/main/java/com/rama/colibri/MainActivity.kt b/app/src/main/java/com/rama/colibri/MainActivity.kt\nindex a409f6b..0df48a2 100644\n--- a/app/src/main/java/com/rama/colibri/MainActivity.kt\n+++ b/app/src/main/java/com/rama/colibri/MainActivity.kt\n@@ -6,35 +6,106 @@ import android.content.pm.ResolveInfo\n import android.os.Bundle\n import android.widget.ArrayAdapter\n import android.widget.ListView\n+import android.widget.TextView\n+import android.view.View\n+\n+/* ---------- Pure data & formatting ---------- */\n+\n+data class StatusInfo(\n+    val date: String?,\n+    val temperature: String?,\n+    val battery: String?\n+)\n+\n+fun buildStatusLine(info: StatusInfo): String {\n+    return listOfNotNull(\n+        info.date,\n+        info.temperature,\n+        info.battery\n+    ).joinToString(\"  |  \")\n+}\n+\n+/* ---------- Activity ---------- */\n \n class MainActivity : Activity() {\n \n+    private lateinit var statusText: TextView\n+    private lateinit var listView: ListView\n+\n+    private var currentInfo = StatusInfo(\n+        date = null,\n+        temperature = null,\n+        battery = null\n+    )\n+\n     override fun onCreate(savedInstanceState: Bundle?) {\n         super.onCreate(savedInstanceState)\n+\n+        // Hide status bar for API 26+\n+        @Suppress(\"DEPRECATION\")\n+        window.decorView.systemUiVisibility =\n+            View.SYSTEM_UI_FLAG_FULLSCREEN or\n+            View.SYSTEM_UI_FLAG_LAYOUT_FULLSCREEN or\n+            View.SYSTEM_UI_FLAG_LAYOUT_STABLE\n+\n         setContentView(R.layout.activity_main)\n \n-        val listView = findViewById<ListView>(R.id.appList)\n+        statusText = findViewById(R.id.date)\n+        listView = findViewById(R.id.appList)\n+\n+        setupAppList()\n+\n+        // Initial demo values (replace later)\n+        updateDate(\"20 Dez 2025\")\n+        updateTemperature(\"33°F\")\n+        updateBattery(\"42%\")\n+    }\n+\n+    /* ---------- UI updates ---------- */\n \n+    private fun updateDate(date: String) {\n+        currentInfo = currentInfo.copy(date = date)\n+        refreshStatusLine()\n+    }\n+\n+    private fun updateTemperature(temp: String) {\n+        currentInfo = currentInfo.copy(temperature = temp)\n+        refreshStatusLine()\n+    }\n+\n+    private fun updateBattery(battery: String) {\n+        currentInfo = currentInfo.copy(battery = battery)\n+        refreshStatusLine()\n+    }\n+\n+    private fun refreshStatusLine() {\n+        statusText.text = buildStatusLine(currentInfo)\n+    }\n+\n+    /* ---------- App list ---------- */\n+\n+    private fun setupAppList() {\n         val pm = packageManager\n+\n         val intent = Intent(Intent.ACTION_MAIN, null).apply {\n             addCategory(Intent.CATEGORY_LAUNCHER)\n         }\n \n-        val apps: List<ResolveInfo> = pm.queryIntentActivities(intent, 0)\n-            .sortedBy { it.loadLabel(pm).toString().lowercase() }\n+        val apps: List<ResolveInfo> =\n+            pm.queryIntentActivities(intent, 0)\n+                .sortedBy { it.loadLabel(pm).toString().lowercase() }\n \n         val labels = apps.map { it.loadLabel(pm).toString() }\n \n-        val adapter = ArrayAdapter(\n+        listView.adapter = ArrayAdapter(\n             this,\n             android.R.layout.simple_list_item_1,\n             labels\n         )\n \n-        listView.adapter = adapter\n-\n         listView.setOnItemClickListener { _, _, position, _ ->\n             val app = apps[position]\n+\n             val launchIntent = Intent().apply {\n                 setClassName(\n                     app.activityInfo.packageName,\n@@ -42,6 +113,7 @@ class MainActivity : Activity() {\n                 )\n                 addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)\n             }\n+\n             startActivity(launchIntent)\n         }\n     }\n"
      },
