      "app/src/androidTest/java/com/rama/colibri/ExampleInstrumentedTest.kt": {
        "binary": false,
        "truncated": false,
        "patch": "diff --git a/app/src/androidTest/java/com/rama/colibri/ExampleInstrumentedTest.kt b/app/src/androidTest/java/com/rama/colibri/ExampleInstrumentedTest.kt\nnew file mode 100644\nindex 0000000..2ce460b\n--- /dev/null\n+++ b/app/src/androidTest/java/com/rama/colibri/ExampleInstrumentedTest.kt\n@@ -0,0 +1,24 @@\n+package com.rama.colibri\n+\n+import androidx.test.platform.app.InstrumentationRegistry\n+import androidx.test.ext.junit.runners.AndroidJUnit4\n+\n+import org.junit.Test\n+import org.junit.runner.RunWith\n+\n+import org.junit.Assert.*\n+\n+/**\n+ * Instrumented test, which will execute on an Android device.\n+ *\n+ * See [testing documentation](http://d.android.com/tools/testing).\n+ */\n+@RunWith(AndroidJUnit4::class)\n+class ExampleInstrumentedTest {\n+    @Test\n+    fun useAppContext() {\n+        // Context of the app under test.\n+        val appContext = InstrumentationRegistry.getInstrumentation().targetContext\n+        assertEquals(\"com.rama.colibri\", appContext.packageName)\n+    }\n+}\n\\ No newline at end of file\n"
      },
      "app/src/main/AndroidManifest.xml": {
        "binary": false,
        "truncated": false,
        "patch": "diff --git a/app/src/main/AndroidManifest.xml b/app/src/main/AndroidManifest.xml\nnew file mode 100644\nindex 0000000..1201dba\n--- /dev/null\n+++ b/app/src/main/AndroidManifest.xml\n@@ -0,0 +1,23 @@\n+<?xml version=\"1.0\" encoding=\"utf-8\"?>\n+<manifest xmlns:android=\"http://schemas.android.com/apk/res/android\"\n+    xmlns:tools=\"http://schemas.android.com/tools\">\n+\n+    <application\n+        android:icon=\"@mipmap/ic_launcher\"\n+        android:label=\"@string/app_name\"\n+        android:roundIcon=\"@mipmap/ic_launcher_round\"\n+        android:supportsRtl=\"true\"\n+        android:theme=\"@style/Theme.Colibri\">\n+        <activity\n+            android:name=\".MainActivity\"\n+            android:exported=\"true\"\n+            android:launchMode=\"singleTask\">\n+            <intent-filter>\n+                <action android:name=\"android.intent.action.MAIN\" />\n+                <category android:name=\"android.intent.category.HOME\" />\n+                <category android:name=\"android.intent.category.DEFAULT\" />\n+            </intent-filter>\n+        </activity>\n+    </application>\n+\n+</manifest>\n\\ No newline at end of file\n"
      },
      "app/src/main/java/com/rama/colibri/MainActivity.kt": {
        "binary": false,
        "truncated": false,
        "patch": "diff --git a/app/src/main/java/com/rama/colibri/MainActivity.kt b/app/src/main/java/com/rama/colibri/MainActivity.kt\nnew file mode 100644\nindex 0000000..5ed5462\n--- /dev/null\n+++ b/app/src/main/java/com/rama/colibri/MainActivity.kt\n@@ -0,0 +1,48 @@\n+package com.example.minimallauncher\n+\n+import android.app.Activity\n+import android.content.Intent\n+import android.content.pm.ResolveInfo\n+import android.os.Bundle\n+import android.widget.ArrayAdapter\n+import android.widget.ListView\n+\n+class MainActivity : Activity() {\n+\n+    override fun onCreate(savedInstanceState: Bundle?) {\n+        super.onCreate(savedInstanceState)\n+        setContentView(R.layout.activity_main)\n+\n+        val listView = findViewById<ListView>(R.id.appList)\n+\n+        val pm = packageManager\n+        val intent = Intent(Intent.ACTION_MAIN, null).apply {\n+            addCategory(Intent.CATEGORY_LAUNCHER)\n+        }\n+\n+        val apps: List<ResolveInfo> = pm.queryIntentActivities(intent, 0)\n+            .sortedBy { it.loadLabel(pm).toString().lowercase() }\n+\n+        val labels = apps.map { it.loadLabel(pm).toString() }\n+\n+        val adapter = ArrayAdapter(\n+            this,\n+            android.R.layout.simple_list_item_1,\n+            labels\n+        )\n+\n+        listView.adapter = adapter\n+\n+        listView.setOnItemClickListener { _, _, position, _ ->\n+            val app = apps[position]\n+            val launchIntent = Intent().apply {\n+                setClassName(\n+                    app.activityInfo.packageName,\n+                    app.activityInfo.name\n+                )\n+                addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)\n+            }\n+            startActivity(launchIntent)\n+        }\n+    }\n+}\n"
      },
